8	///
9	/// \file
10	/// Implementation header for a block of memory.
11	///
12	//===----------------------------------------------------------------------===//
13	
14	#ifndef LLVM_LIBC_SRC___SUPPORT_BLOCK_H
15	#define LLVM_LIBC_SRC___SUPPORT_BLOCK_H
16	
17	#include "hdr/stdint_proxy.h"
18	#include "hdr/types/size_t.h"
19	#include "src/__support/CPP/algorithm.h"
20	#include "src/__support/CPP/cstddef.h"
21	#include "src/__support/CPP/limits.h"
22	#include "src/__support/CPP/new.h"
23	#include "src/__support/CPP/optional.h"
24	#include "src/__support/CPP/span.h"
25	#include "src/__support/libc_assert.h"
26	#include "src/__support/macros/config.h"
27	#include "src/__support/math_extras.h"
28	#include "src/string/memory_utils/inline_memcpy.h"
29	
30	namespace LIBC_NAMESPACE_DECL {
31	
32	/// Returns the value rounded down to the nearest multiple of alignment.
33	LIBC_INLINE constexpr size_t align_down(size_t value, size_t alignment) {
34	  // Note this shouldn't overflow since the result will always be <= value.
35	  return (value / alignment) * alignment;
36	}
37	
38	/// Returns the value rounded up to the nearest multiple of alignment. May wrap
39	/// around.
40	LIBC_INLINE constexpr size_t align_up(size_t value, size_t alignment) {
41	  return align_down(value + alignment - 1, alignment);
42	}
43	
44	using ByteSpan = cpp::span<LIBC_NAMESPACE::cpp::byte>;
45	using cpp::optional;
46	
47	/// Reference to a memory region with links to adjacent blocks.
48	///
49	/// The blocks store their offsets to the previous and next blocks. The latter
50	/// is also the block's size. The metadata is stored in raw bytes and accessed
51	/// through aligned byte-copy loads and stores so the header can overlap user
52	/// storage without creating typed aliasing accesses.
53	///
54	/// All blocks have their usable space aligned to some multiple of MIN_ALIGN.
55	/// This also implies that block outer sizes are aligned to MIN_ALIGN.
56	///
57	/// As an example, the diagram below represents two contiguous blocks. The
58	/// indices indicate byte offsets:
59	///
60	/// @code{.unparsed}
61	/// Block 1:
62	/// +---------------------+--------------+
63	/// | Header              | Usable space |
64	/// +----------+----------+--------------+
65	/// | prev     | next     |              |
66	/// | 0......3 | 4......7 | 8........227 |
67	/// | 00000000 | 00000230 |  <app data>  |
68	/// +----------+----------+--------------+
69	/// Block 2:
70	/// +---------------------+--------------+
71	/// | Header              | Usable space |
72	/// +----------+----------+--------------+
73	/// | prev     | next     |              |
74	/// | 0......3 | 4......7 | 8........827 |
75	/// | 00000230 | 00000830 | f7f7....f7f7 |
76	/// +----------+----------+--------------+
77	/// @endcode
78	///
79	/// As a space optimization, when a block is allocated, it consumes the prev
80	/// field of the following block:
81	///
82	/// Block 1 (used):
83	/// +---------------------+--------------+
84	/// | Header              | Usable space |
85	/// +----------+----------+--------------+
86	/// | prev     | next     |              |
87	/// | 0......3 | 4......7 | 8........230 |
88	/// | 00000000 | 00000230 |  <app data>  |
89	/// +----------+----------+--------------+
90	/// Block 2:
91	/// +---------------------+--------------+
92	/// | B1       | Header   | Usable space |
93	/// +----------+----------+--------------+
94	/// |          | next     |              |
95	/// | 0......3 | 4......7 | 8........827 |
96	/// | xxxxxxxx | 00000830 | f7f7....f7f7 |
97	/// +----------+----------+--------------+
98	///
99	/// The next offset of a block matches the previous offset of its next block.
100	/// The first block in a list is denoted by having a previous offset of `0`.
101	class BlockRef {
102	  // Masks for the contents of the next field.
103	  static constexpr size_t PREV_FREE_MASK = 1 << 0;
104	  static constexpr size_t LAST_MASK = 1 << 1;
105	  static constexpr size_t SIZE_MASK = ~(PREV_FREE_MASK | LAST_MASK);
106	
107	  // Header field offsets. The value at PREV_OFFSET is only meaningful when the
108	  // PREV_FREE_MASK bit is set in the next field.
109	  static constexpr size_t PREV_OFFSET = 0;
110	  static constexpr size_t NEXT_OFFSET = PREV_OFFSET + sizeof(size_t);
111	
112	public:
113	  static constexpr size_t HEADER_SIZE = NEXT_OFFSET + sizeof(size_t);
114	
115	  // To ensure block sizes have two lower unused bits, ensure usable space is
116	  // always aligned to at least 4 bytes. (The distances between usable spaces,
117	  // the outer size, is then always also 4-aligned.)
118	  static constexpr size_t MIN_ALIGN = cpp::max(size_t{4}, alignof(max_align_t));
119	
120	  LIBC_INLINE constexpr BlockRef() = default;
121	  LIBC_INLINE explicit constexpr BlockRef(cpp::byte *header_ptr)
122	      : header_ptr(header_ptr) {}
123	  LIBC_INLINE explicit constexpr operator bool() const {
124	    return header_ptr != nullptr;
125	  }
126	  LIBC_INLINE constexpr bool operator==(BlockRef other) const {
127	    return header_ptr == other.header_ptr;
128	  }
129	  LIBC_INLINE constexpr bool operator!=(BlockRef other) const {
130	    return !(*this == other);
131	  }
132	
133	  LIBC_INLINE uintptr_t addr() const {
134	    return reinterpret_cast<uintptr_t>(header_ptr);
135	  }
136	
137	  /// Initializes a given memory region into a first block and a sentinel last
138	  /// block. Returns the first block, which has its usable space aligned to
139	  /// MIN_ALIGN.
140	  static optional<BlockRef> init(ByteSpan region);
141	
142	  /// @returns  A pointer to a block, given a pointer to the start of the usable
143	  ///           space inside the block.
144	  ///
145	  /// This is the inverse of `usable_space()`.
146	  ///
147	  /// @warning  This method does not do any checking; passing a random pointer
148	  ///           will return a non-null pointer.
149	  LIBC_INLINE static BlockRef from_usable_space(void *usable_space) {
150	    LIBC_ASSERT(usable_space != nullptr && "usable space cannot be null");
151	    auto *bytes = reinterpret_cast<cpp::byte *>(usable_space);
152	    return BlockRef(bytes - HEADER_SIZE);
153	  }
154	  LIBC_INLINE static BlockRef from_usable_space(const void *usable_space) {
155	    LIBC_ASSERT(usable_space != nullptr && "usable space cannot be null");
156	    const auto *bytes = reinterpret_cast<const cpp::byte *>(usable_space);
157	    return BlockRef(const_cast<cpp::byte *>(bytes - HEADER_SIZE));
158	  }
159	
160	  /// @returns The total size of the block in bytes, including the header.
161	  LIBC_INLINE size_t outer_size() const { return load_next() & SIZE_MASK; }
162	
163	  LIBC_INLINE static constexpr size_t outer_size(size_t inner_size) {
164	    // The usable region includes the prev field of the next block.
165	    return inner_size - PREV_FIELD_SIZE + HEADER_SIZE;
166	  }
167	
168	  /// @returns The number of usable bytes inside the block were it to be
169	  /// allocated.
170	  LIBC_INLINE size_t inner_size() const {
171	    if (!next())
172	      return 0;
173	    return inner_size(outer_size());
174	  }
175	
176	  /// @returns The number of usable bytes inside a block with the given outer
177	  /// size were it to be allocated.
178	  LIBC_INLINE static constexpr size_t inner_size(size_t outer_size) {
179	    // The usable region includes the prev field of the next block.
180	    return inner_size_free(outer_size) + PREV_FIELD_SIZE;
181	  }
182	
183	  /// @returns The number of usable bytes inside the block if it remains free.
184	  LIBC_INLINE size_t inner_size_free() const {
185	    if (!next())
186	      return 0;
187	    return inner_size_free(outer_size());
188	  }
189	
190	  /// @returns The number of usable bytes inside a block with the given outer
191	  /// size if it remains free.
192	  LIBC_INLINE static constexpr size_t inner_size_free(size_t outer_size) {
193	    return outer_size - HEADER_SIZE;
194	  }
195	
196	  /// @returns A pointer to the usable space inside this block.
197	  ///
198	  /// Aligned to some multiple of MIN_ALIGN.
199	  LIBC_INLINE cpp::byte *usable_space() const {
200	    auto *s = nonnull_header_ptr() + HEADER_SIZE;
201	    LIBC_ASSERT(reinterpret_cast<uintptr_t>(s) % MIN_ALIGN == 0 &&
202	                "usable space must be aligned to MIN_ALIGN");
203	    return s;
204	  }
205	
206	  // @returns The region of memory the block manages, including the header.
207	  LIBC_INLINE ByteSpan region() const {
208	    return {nonnull_header_ptr(), outer_size()};
209	  }
210	
211	  /// Attempts to split this block.
212	  ///
213	  /// If successful, the block will have an inner size of at least
214	  /// `new_inner_size`. The remaining space will be returned as a new block,
215	  /// with usable space aligned to `usable_space_alignment`. Note that the prev
216	  /// field of the next block counts as part of the inner size of the block.
217	  /// `usable_space_alignment` must be a multiple of MIN_ALIGN.
218	  optional<BlockRef> split(size_t new_inner_size,
219	                           size_t usable_space_alignment = MIN_ALIGN) const;
220	
221	  /// Merges this block with the one that comes after it.
222	  bool merge_next() const;
223	
224	  /// @returns The block immediately after this one, or a null block if this is
225	  /// the last block.
226	  LIBC_INLINE BlockRef next() const {
227	    size_t next_value = load_next();
228	    if (next_value & LAST_MASK)
229	      return BlockRef();
230	    return BlockRef(nonnull_header_ptr() + (next_value & SIZE_MASK));
231	  }
232	
233	  /// @returns The free block immediately before this one, otherwise null.
234	  LIBC_INLINE BlockRef prev_free() const {
235	    if (!(load_next() & PREV_FREE_MASK))
236	      return BlockRef();
237	    return BlockRef(nonnull_header_ptr() - load_prev());
238	  }
239	
240	  /// @returns Whether the block is unavailable for allocation.
241	  LIBC_INLINE bool used() const { return !next() || !next().prev_free(); }
242	
243	  /// Marks this block as in use.
244	  LIBC_INLINE void mark_used() const {
245	    LIBC_ASSERT(next() && "last block is always considered used");
246	    BlockRef next_block = next();
247	    next_block.store_next(next_block.load_next() & ~PREV_FREE_MASK);
248	  }
249	
250	  /// Marks this block as free.
251	  LIBC_INLINE void mark_free() const {
252	    LIBC_ASSERT(next() && "last block is always considered used");
253	    BlockRef next_block = next();
254	    next_block.store_next(next_block.load_next() | PREV_FREE_MASK);
255	    next_block.store_prev(outer_size());
256	  }
257	
258	  LIBC_INLINE bool is_usable_space_aligned(size_t alignment) const {
259	    return reinterpret_cast<uintptr_t>(usable_space()) % alignment == 0;
260	  }
261	
262	  // Returns the minimum inner size necessary for a block of that size to
263	  // always be able to allocate at the given size and alignment.
264	  //
265	  // Returns 0 if there is no such size.
266	  LIBC_INLINE static size_t min_size_for_allocation(size_t alignment,
267	                                                    size_t size) {
268	    LIBC_ASSERT(alignment >= MIN_ALIGN && alignment % MIN_ALIGN == 0 &&
269	                "alignment must be multiple of MIN_ALIGN");
270	
271	    if (alignment == MIN_ALIGN)
272	      return size;
273	
274	    // We must create a new block inside this one (splitting). This requires a
275	    // block header in addition to the requested size.
276	    if (add_overflow(size, HEADER_SIZE, size))
277	      return 0;
278	
279	    // Beyond that, padding space may need to remain in this block to ensure
280	    // that the usable space of the next block is aligned.
281	    //
282	    // Consider a position P of some lesser alignment, L, with maximal distance
283	    // to the next position of some greater alignment, G, where G is a multiple
284	    // of L. P must be one L unit past a G-aligned point. If it were one L-unit
285	    // earlier, its distance would be zero. If it were one L-unit later, its
286	    // distance would not be maximal. If it were not some integral number of L
287	    // units away, it would not be L-aligned.
288	    //
289	    // So the maximum distance would be G - L. As a special case, if L is 1
290	    // (unaligned), the max distance is G - 1.
291	    //
292	    // This block's usable space is aligned to MIN_ALIGN >= header alignment.
293	    // With zero padding, the next block's usable space is HEADER_SIZE past it,
294	    // which is aligned to header alignment. Thus the max padding needed is
295	    // alignment - alignof(size_t).
296	    if (add_overflow(size, alignment - alignof(size_t), size))
297	      return 0;
298	    return size;
299	  }
300	
301	  struct BlockInfo;
302	
303	  // Divide a block into up to 3 blocks according to `BlockInfo`. Behavior is
304	  // undefined if allocation is not possible for the given size and alignment.
305	  static BlockInfo allocate(BlockRef block, size_t alignment, size_t size);
306	
307	  // These two functions may wrap around.
308	  LIBC_INLINE static uintptr_t
309	  next_possible_block_start(uintptr_t ptr,
310	                            size_t usable_space_alignment = MIN_ALIGN) {
311	    return align_up(ptr + HEADER_SIZE, usable_space_alignment) - HEADER_SIZE;
312	  }
313	  LIBC_INLINE static uintptr_t
314	  prev_possible_block_start(uintptr_t ptr,
315	                            size_t usable_space_alignment = MIN_ALIGN) {
316	    return align_down(ptr, usable_space_alignment) - HEADER_SIZE;
317	  }
318	
319	  /// Only for testing.
320	  static constexpr size_t PREV_FIELD_SIZE = sizeof(size_t);
321	
322	private:
323	  /// Construct a block to represent a span of bytes. Overwrites only enough
324	  /// memory for the block header; the rest of the span is left alone.
325	  LIBC_INLINE static BlockRef as_block(ByteSpan bytes) {
326	    LIBC_ASSERT(reinterpret_cast<uintptr_t>(bytes.data()) % alignof(size_t) ==
327	                    0 &&
328	                "block start must be suitably aligned");
329	    LIBC_ASSERT(bytes.size() % MIN_ALIGN == 0 &&
330	                "block size must be aligned to MIN_ALIGN");
331	    BlockRef block(bytes.data());
332	    block.store_next(bytes.size());
333	    return block;
334	  }
335	
336	  LIBC_INLINE static void make_last_block(cpp::byte *start) {
337	    LIBC_ASSERT(reinterpret_cast<uintptr_t>(start) % alignof(size_t) == 0 &&
338	                "block start must be suitably aligned");
339	    BlockRef last(start);
340	    last.store_next(HEADER_SIZE | LAST_MASK);
341	  }
342	
343	  LIBC_INLINE cpp::byte *field_ptr(size_t offset) const {
344	    cpp::byte *ptr = nonnull_header_ptr() + offset;
345	    LIBC_ASSERT(reinterpret_cast<uintptr_t>(ptr) % alignof(size_t) == 0 &&
346	                "block metadata fields must be aligned");
347	    return ptr;
348	  }
349	
350	  LIBC_INLINE size_t load_field(size_t offset) const {
351	    return *reinterpret_cast<const size_t *>(field_ptr(offset));
352	  }
353	
354	  LIBC_INLINE void store_field(size_t offset, size_t value) const {
355	    new (field_ptr(offset)) size_t(value);
356	  }
357	
358	  /// Offset from this block to the previous block. 0 if this is the first
359	  /// block. This field is only alive when the previous block is free;
360	  /// otherwise, its memory is reused as part of the previous block's usable
361	  /// space.
362	  LIBC_INLINE size_t load_prev() const { return load_field(PREV_OFFSET); }
363	
364	  /// Offset from this block to the next block. Valid even if this is the last
365	  /// block, since it equals the size of the block.
366	  ///
367	  /// Information about the current state of the block is stored in the two low
368	  /// order bits of the next_ value. These are guaranteed free by a minimum
369	  /// alignment (and thus, alignment of the size) of 4. The lowest bit is the
370	  /// `prev_free` flag, and the other bit is the `last` flag.
371	  ///
372	  /// * If the `prev_free` flag is set, the block isn't the first and the
373	  ///   previous block is free.
374	  /// * If the `last` flag is set, the block is the sentinel last block. It is
375	  ///   summarily considered used and has no next block.
376	  LIBC_INLINE size_t load_next() const { return load_field(NEXT_OFFSET); }
377	
378	  LIBC_INLINE void store_prev(size_t value) const {
379	    store_field(PREV_OFFSET, value);
380	  }
381	  LIBC_INLINE void store_next(size_t value) const {
382	    store_field(NEXT_OFFSET, value);
383	  }
384	
385	  LIBC_INLINE cpp::byte *nonnull_header_ptr() const {
386	    LIBC_ASSERT(header_ptr != nullptr && "operation on an invalid block");
387	#if __has_builtin(__builtin_assume)
388	    __builtin_assume(header_ptr != nullptr);
389	#endif
390	    return header_ptr;
391	  }
392	
393	  cpp::byte *header_ptr = nullptr;
394	};
395	
396	// This is the return type for `allocate` which can split one block into up to
397	// three blocks.
398	struct BlockRef::BlockInfo {
399	  // This is the newly aligned block. It will have the alignment requested by a
400	  // call to `allocate` and at most `size`.
401	  BlockRef block;
402	
403	  // If the usable_space in the new block was not aligned according to the
404	  // `alignment` parameter, we will need to split into this block and the
405	  // `block` to ensure `block` is properly aligned. In this case, `prev` will be
406	  // this new "padding" block. `prev` will be null if no new block was created
407	  // or we were able to merge the block before the original block with the
408	  // "padding" block.
409	  BlockRef prev;
410	
411	  // This is the remainder of the next block after splitting the `block`
412	  // according to `size`. This can happen if there's enough space after the
413	  // `block`.
414	  BlockRef next;
415	};
416	
417	LIBC_INLINE
418	optional<BlockRef> BlockRef::init(ByteSpan region) {
419	  if (!region.data())
420	    return {};
421	
422	  uintptr_t start = reinterpret_cast<uintptr_t>(region.data());
423	  uintptr_t end = start + region.size();
424	  if (end < start)
425	    return {};
426	
427	  uintptr_t block_start = next_possible_block_start(start);
428	  if (block_start < start)
429	    return {};
430	
431	  uintptr_t last_start = prev_possible_block_start(end);
432	  if (last_start >= end)
433	    return {};
434	
435	  if (block_start + HEADER_SIZE > last_start)
436	    return {};
437	
438	  auto *last_start_ptr = reinterpret_cast<cpp::byte *>(last_start);
439	  BlockRef block =
440	      as_block({reinterpret_cast<cpp::byte *>(block_start), last_start_ptr});
441	  make_last_block(last_start_ptr);
442	  block.mark_free();
443	  return block;
444	}
445	
446	LIBC_INLINE
447	BlockRef::BlockInfo BlockRef::allocate(BlockRef block, size_t alignment,
448	                                       size_t size) {
449	  LIBC_ASSERT(block.header_ptr != nullptr &&
450	              "allocating from an invalid block");
451	  LIBC_ASSERT(alignment % MIN_ALIGN == 0 &&
452	              "alignment must be a multiple of MIN_ALIGN");
453	
454	  BlockInfo info{block, BlockRef(), BlockRef()};
455	
456	  if (!info.block.is_usable_space_aligned(alignment)) {
457	    BlockRef original = info.block;
458	    // The padding block has no minimum size requirement.
459	    optional<BlockRef> maybe_aligned_block = original.split(0, alignment);
460	    LIBC_ASSERT(maybe_aligned_block.has_value() &&
461	                "it should always be possible to split for alignment");
462	
463	    if (BlockRef prev = original.prev_free()) {
464	      // If there is a free block before this, we can merge the current one with
465	      // the newly created one.
466	      prev.merge_next();
467	    } else {
468	      info.prev = original;
469	    }
470	
471	    BlockRef aligned_block = *maybe_aligned_block;
472	    LIBC_ASSERT(aligned_block.is_usable_space_aligned(alignment) &&
473	                "The aligned block isn't aligned somehow.");
474	    info.block = aligned_block;
475	  }
476	
477	  // Now get a block for the requested size.
478	  if (optional<BlockRef> next = info.block.split(size))
479	    info.next = *next;
480	
481	  return info;
482	}
483	
484	LIBC_INLINE
485	optional<BlockRef> BlockRef::split(size_t new_inner_size,
486	                                   size_t usable_space_alignment) const {
487	  LIBC_ASSERT(usable_space_alignment % MIN_ALIGN == 0 &&
488	              "alignment must be a multiple of MIN_ALIGN");
489	
490	  // Compute the minimum outer size that produces a block of at least
491	  // `new_inner_size`.
492	  size_t min_outer_size = outer_size(cpp::max(new_inner_size, PREV_FIELD_SIZE));
493	
494	  uintptr_t start = addr();
495	  uintptr_t next_block_start =
496	      next_possible_block_start(start + min_outer_size, usable_space_alignment);
497	  if (next_block_start < start)
498	    return {};
499	  size_t new_outer_size = next_block_start - start;
500	  LIBC_ASSERT(new_outer_size % MIN_ALIGN == 0 &&
501	              "new size must be aligned to MIN_ALIGN");
502	
503	  if (outer_size() < new_outer_size ||
504	      outer_size() - new_outer_size < HEADER_SIZE)
505	    return {};
506	
507	  bool was_free = !used();
508	
509	  ByteSpan new_region = region().subspan(new_outer_size);
510	  store_next((load_next() & ~SIZE_MASK) | new_outer_size);
511	
512	  BlockRef new_block = as_block(new_region);
513	  new_block.mark_free();
514	  if (was_free)
515	    mark_free();
516	
517	  LIBC_ASSERT(new_block.is_usable_space_aligned(usable_space_alignment) &&
518	              "usable space must have requested alignment");
519	  return new_block;
520	}
521	
522	LIBC_INLINE
523	bool BlockRef::merge_next() const {
524	  BlockRef next_block = next();
525	  if (used() || next_block.used())
526	    return false;
527	  size_t new_size = outer_size() + next_block.outer_size();
528	  store_next((load_next() & ~SIZE_MASK) | new_size);
529	  next().store_prev(new_size);
530	  return true;
531	}
532	
533	} // namespace LIBC_NAMESPACE_DECL
534	
535	#endif // LLVM_LIBC_SRC___SUPPORT_BLOCK_H
