21	/// A trie of free lists.
22	///
23	/// This is an unusual little data structure originally from Doug Lea's malloc.
24	/// Finding the best fit from a set of differently-sized free list typically
25	/// required some kind of ordered map, and these are typically implemented using
26	/// a self-balancing binary search tree. Those are notorious for having a
27	/// relatively large number of special cases, while this trie has relatively
28	/// few, which helps with code size.
29	///
30	/// Operations on the trie are logarithmic not on the number of nodes within it,
31	/// but rather the fixed range of possible sizes that the trie can contain. This
32	/// means that the data structure would likely actually perform worse than an
33	/// e.g. red-black tree, but its implementation is still much simpler.
34	///
35	/// Each trie node's children subdivide the range of possible sizes into two
36	/// halves: a lower and an upper. The node itself holds a free list of some size
37	/// within its range. This makes it possible to summarily replace any node with
38	/// any leaf within its subtrie, which makes it very straightforward to remove a
39	/// node. Insertion is also simple; the only real complexity lies with finding
40	/// the best fit. This can still be done in logarithmic time with only a few
41	/// cases to consider.
42	///
43	/// The trie refers to, but does not own, the Nodes that comprise it.
44	class FreeTrie {
45	public:
46	  /// A trie node that is also a free list. Only the head node of each list is
47	  /// actually part of the trie. The subtrie contains a continous SizeRange of
48	  /// free lists. The lower and upper subtrie's contain the lower and upper half
49	  /// of the subtries range. There is no direct relationship between the size of
50	  /// this node's free list and the contents of the lower and upper subtries.
51	  class Node : public FreeList::Node {
52	    /// The child subtrie covering the lower half of this subtrie's size range.
53	    /// Undefined if this is not the head of the list.
54	    Node *lower;
55	    /// The child subtrie covering the upper half of this subtrie's size range.
56	    /// Undefined if this is not the head of the list.
57	    Node *upper;
58	    /// The parent subtrie. nullptr if this is the root or not the head of the
59	    /// list.
60	    Node *parent;
61	
62	    friend class FreeTrie;
63	  };
64	
65	  /// Power-of-two range of sizes covered by a subtrie.
66	  struct SizeRange {
67	    size_t min;
68	    size_t width;
69	
70	    LIBC_INLINE constexpr SizeRange(size_t min, size_t width)
71	        : min(min), width(width) {
72	      LIBC_ASSERT(!(width & (width - 1)) && "width must be a power of two");
73	    }
74	
75	    /// @returns The lower half of the size range.
76	    LIBC_INLINE SizeRange lower() const { return {min, width / 2}; }
77	
78	    /// @returns The upper half of the size range.
79	    LIBC_INLINE SizeRange upper() const { return {min + width / 2, width / 2}; }
80	
81	    /// @returns The largest size in this range.
82	    LIBC_INLINE size_t max() const { return min + (width - 1); }
83	
84	    /// @returns Whether the range contains the given size.
85	    LIBC_INLINE bool contains(size_t size) const {
86	      return min <= size && size < min + width;
87	    }
88	  };
89	
90	  LIBC_INLINE constexpr FreeTrie() : FreeTrie(SizeRange{0, 0}) {}
91	  LIBC_INLINE constexpr FreeTrie(SizeRange range) : range(range) {}
92	
93	  /// Sets the range of possible block sizes. This can only be called when the
94	  /// trie is empty.
95	  LIBC_INLINE void set_range(FreeTrie::SizeRange new_range) {
96	    LIBC_ASSERT(empty() && "cannot change the range of a preexisting trie");
97	    range = new_range;
98	  }
99	
100	  /// @returns Whether the trie contains any blocks.
101	  LIBC_INLINE bool empty() const { return !root; }
102	
103	  /// Push a block to the trie.
104	  void push(BlockRef block);
105	
106	  /// Remove a node from this trie node's free list.
107	  void remove(Node *node);
108	
109	  /// @returns A smallest node that can allocate the given size; otherwise
110	  /// nullptr.
111	  Node *find_best_fit(size_t size);
112	
113	private:
114	  /// @returns Whether a node is the head of its containing freelist.
115	  bool is_head(Node *node) const { return node->parent || node == root; }
116	
117	  /// Replaces references to one node with another (or nullptr) in all adjacent
118	  /// parent and child nodes.
119	  void replace_node(Node *node, Node *new_node);
120	
121	  Node *root = nullptr;
122	  SizeRange range;
123	};
124	
125	LIBC_INLINE void FreeTrie::push(BlockRef block) {
126	  LIBC_ASSERT(block.inner_size_free() >= sizeof(Node) &&
127	              "block too small to accomodate free trie node");
128	  size_t size = block.inner_size();
129	  LIBC_ASSERT(range.contains(size) && "requested size out of trie range");
130	
131	  // Find the position in the tree to push to.
132	  Node **cur = &root;
133	  Node *parent = nullptr;
134	  SizeRange cur_range = range;
135	  while (*cur && (*cur)->size() != size) {
136	    LIBC_ASSERT(cur_range.contains(size) && "requested size out of trie range");
137	    parent = *cur;
138	    if (size <= cur_range.lower().max()) {
139	      cur = &(*cur)->lower;
140	      cur_range = cur_range.lower();
141	    } else {
142	      cur = &(*cur)->upper;
143	      cur_range = cur_range.upper();
144	    }
145	  }
146	
147	  Node *node = new (block.usable_space()) Node;
148	  FreeList list = *cur;
149	  if (list.empty()) {
150	    node->parent = parent;
151	    node->lower = node->upper = nullptr;
152	  } else {
153	    node->parent = nullptr;
154	  }
155	  list.push(node);
156	  *cur = static_cast<Node *>(list.begin());
157	}
158	
159	LIBC_INLINE FreeTrie::Node *FreeTrie::find_best_fit(size_t size) {
160	  if (empty() || range.max() < size)
161	    return nullptr;
162	
163	  Node *cur = root;
164	  SizeRange cur_range = range;
165	  Node *best_fit = nullptr;
166	  Node *deferred_upper_trie = nullptr;
167	  FreeTrie::SizeRange deferred_upper_range{0, 0};
168	
169	  while (true) {
170	    LIBC_ASSERT(cur_range.contains(cur->size()) &&
171	                "trie node size out of range");
172	    LIBC_ASSERT(cur_range.max() >= size &&
173	                "range could not fit requested size");
174	    LIBC_ASSERT((!best_fit || cur_range.min < best_fit->size()) &&
175	                "range could not contain a best fit");
176	
177	    // If the current node is an exact fit, it is a best fit.
178	    if (cur->size() == size)
179	      return cur;
180	
181	    if (cur->size() > size && (!best_fit || cur->size() < best_fit->size())) {
182	      // The current node is a better fit.
183	      best_fit = cur;
184	
185	      // If there is a deferred upper subtrie, then the current node is
186	      // somewhere in its lower sibling subtrie. That means that the new best
187	      // fit is better than the best fit in the deferred subtrie.
188	      LIBC_ASSERT(
189	          (!deferred_upper_trie ||
190	           deferred_upper_range.min > best_fit->size()) &&
191	          "deferred upper subtrie should be outclassed by new best fit");
192	      deferred_upper_trie = nullptr;
193	    }
194	
195	    // Determine which subtries might contain the best fit.
196	    bool lower_impossible = !cur->lower || cur_range.lower().max() < size;
197	    bool upper_impossible =
198	        !cur->upper ||
199	        // If every node in the lower trie fits
200	        (!lower_impossible && cur_range.min >= size) ||
201	        // If every node in the upper trie is worse than the current best
202	        (best_fit && cur_range.upper().min >= best_fit->size());
203	
204	    if (lower_impossible && upper_impossible) {
205	      if (!deferred_upper_trie)
206	        return best_fit;
207	      // Scan the deferred upper subtrie and consider whether any element within
208	      // provides a better fit.
209	      //
210	      // This can only ever be reached once. In a deferred upper subtrie, every
211	      // node fits, so the higher of two subtries can never contain a best fit.
212	      cur = deferred_upper_trie;
213	      cur_range = deferred_upper_range;
214	      deferred_upper_trie = nullptr;
215	      continue;
216	    }
217	
218	    if (lower_impossible) {
219	      cur = cur->upper;
220	      cur_range = cur_range.upper();
221	    } else if (upper_impossible) {
222	      cur = cur->lower;
223	      cur_range = cur_range.lower();
224	    } else {
225	      // Both subtries might contain a better fit. Any fit in the lower subtrie
226	      // is better than the any fit in the upper subtrie, so scan the lower
227	      // and return to the upper only if no better fits were found. (Any better
228	      // fit found clears the deferred upper subtrie.)
229	      LIBC_ASSERT((!deferred_upper_trie ||
230	                   cur_range.upper().max() < deferred_upper_range.min) &&
231	                  "old deferred upper subtrie should be outclassed by new");
232	      deferred_upper_trie = cur->upper;
233	      deferred_upper_range = cur_range.upper();
234	      cur = cur->lower;
235	      cur_range = cur_range.lower();
236	    }
237	  }
238	}
239	
240	} // namespace LIBC_NAMESPACE_DECL
