8	///
9	/// \file
10	/// Interface for freelist_heap.
11	///
12	//===----------------------------------------------------------------------===//
13	
14	#ifndef LLVM_LIBC_SRC___SUPPORT_FREELIST_HEAP_H
15	#define LLVM_LIBC_SRC___SUPPORT_FREELIST_HEAP_H
16	
17	#include <stddef.h>
18	
19	#include "block.h"
20	#include "freestore.h"
21	#include "src/__support/CPP/optional.h"
22	#include "src/__support/CPP/span.h"
23	#include "src/__support/libc_assert.h"
24	#include "src/__support/macros/config.h"
25	#include "src/__support/math_extras.h"
