27	#include "src/string/memory_utils/inline_memset.h"
28	
29	namespace LIBC_NAMESPACE_DECL {
30	
31	extern "C" cpp::byte _end;
32	extern "C" cpp::byte __llvm_libc_heap_limit;
33	
34	using cpp::optional;
35	using cpp::span;
36	
37	LIBC_INLINE constexpr bool IsPow2(size_t x) { return x && (x & (x - 1)) == 0; }
38	
39	class FreeListHeap {
40	public:
41	  constexpr FreeListHeap() : begin(&_end), end(&__llvm_libc_heap_limit) {}
42	
43	  constexpr FreeListHeap(span<cpp::byte> region)
44	      : begin(region.begin()), end(region.end()) {}
45	
46	  void *allocate(size_t size);
47	  void *aligned_allocate(size_t alignment, size_t size);
48	  // NOTE: All pointers passed to free must come from one of the other
49	  // allocation functions: `allocate`, `aligned_allocate`, `realloc`, `calloc`.
50	  void free(void *ptr);
51	  void *realloc(void *ptr, size_t size);
52	  void *calloc(size_t num, size_t size);
53	  size_t allocation_size(const void *ptr) const;
54	
55	  cpp::span<cpp::byte> region() const { return {begin, end}; }
56	
57	private:
58	  void init();
59	
60	  void *allocate_impl(size_t alignment, size_t size);
61	
62	  span<cpp::byte> block_to_span(BlockRef block) {
63	    return span<cpp::byte>(block.usable_space(), block.inner_size());
64	  }
65	
66	  bool shrink_in_place(BlockRef block, size_t size);
67	
68	  bool is_valid_ptr(const void *ptr) const { return ptr >= begin && ptr < end; }
69	
70	  cpp::byte *begin;
71	  cpp::byte *end;
72	  bool is_initialized = false;
73	  FreeStore free_store;
74	};
75	
76	template <size_t BUFF_SIZE> class FreeListHeapBuffer : public FreeListHeap {
77	public:
78	  constexpr FreeListHeapBuffer() : FreeListHeap{buffer}, buffer{} {}
79	
80	private:
81	  cpp::byte buffer[BUFF_SIZE];
82	};
83	
84	LIBC_INLINE void FreeListHeap::init() {
85	  LIBC_ASSERT(!is_initialized && "duplicate initialization");
86	  auto result = BlockRef::init(region());
87	  BlockRef block = *result;
88	  free_store.set_range({0, cpp::bit_ceil(block.inner_size())});
89	  free_store.insert(block);
90	  is_initialized = true;
91	}
92	
93	LIBC_INLINE void *FreeListHeap::allocate_impl(size_t alignment, size_t size) {
94	  if (size == 0)
95	    return nullptr;
96	
97	  if (!is_initialized)
98	    init();
99	
100	  size_t request_size = BlockRef::min_size_for_allocation(alignment, size);
101	  if (!request_size)
102	    return nullptr;
103	
104	  BlockRef block = free_store.remove_best_fit(request_size);
105	  if (!block)
106	    return nullptr;
107	
108	  auto block_info = BlockRef::allocate(block, alignment, size);
109	  if (block_info.next)
110	    free_store.insert(block_info.next);
111	  if (block_info.prev)
112	    free_store.insert(block_info.prev);
113	
114	  block_info.block.mark_used();
115	  return block_info.block.usable_space();
116	}
117	
118	LIBC_INLINE void *FreeListHeap::allocate(size_t size) {
119	  return allocate_impl(BlockRef::MIN_ALIGN, size);
120	}
121	
122	LIBC_INLINE void *FreeListHeap::aligned_allocate(size_t alignment,
123	                                                 size_t size) {
124	  // The alignment must be an integral power of two.
125	  if (!IsPow2(alignment))
126	    return nullptr;
127	
128	  // The size parameter must be an integral multiple of alignment.
129	  if (size % alignment != 0)
130	    return nullptr;
131	
132	  // The minimum alignment supported by BlockRef is MIN_ALIGN.
133	  alignment = cpp::max(alignment, BlockRef::MIN_ALIGN);
134	
135	  return allocate_impl(alignment, size);
136	}
137	
138	LIBC_INLINE void FreeListHeap::free(void *ptr) {
139	  if (ptr == nullptr)
140	    return;
141	
142	  cpp::byte *bytes = static_cast<cpp::byte *>(ptr);
143	
144	  LIBC_ASSERT(is_valid_ptr(bytes) && "Invalid pointer");
145	
146	  BlockRef block = BlockRef::from_usable_space(bytes);
147	  LIBC_ASSERT(block.next() && "sentinel last block cannot be freed");
148	  LIBC_ASSERT(block.used() && "double free");
149	  block.mark_free();
150	
151	  // Can we combine with the left or right blocks?
152	  BlockRef prev_free = block.prev_free();
153	  BlockRef next = block.next();
154	
155	  if (prev_free) {
156	    // Remove from free store and merge.
157	    free_store.remove(prev_free);
158	    block = prev_free;
159	    block.merge_next();
160	  }
161	  if (!next.used()) {
162	    free_store.remove(next);
163	    block.merge_next();
164	  }
165	  // Add back to the freelist
166	  free_store.insert(block);
167	}
168	
169	LIBC_INLINE size_t FreeListHeap::allocation_size(const void *ptr) const {
170	  if (!is_valid_ptr(ptr))
171	    return 0;
172	  BlockRef block = BlockRef::from_usable_space(ptr);
173	  if (!block.used())
174	    return 0;
175	  return block.inner_size();
176	}
177	
178	LIBC_INLINE bool FreeListHeap::shrink_in_place(BlockRef block, size_t size) {
179	  size_t min_outer_size = BlockRef::outer_size(cpp::max(size, sizeof(size_t)));
180	  uintptr_t next_block_start = BlockRef::next_possible_block_start(
181	      block.addr() + min_outer_size, BlockRef::MIN_ALIGN);
182	  size_t new_outer_size = next_block_start - block.addr();
183	  if (block.outer_size() >= new_outer_size) {
184	    optional<BlockRef> next = block.split(size);
185	    // register the new block on successful split
186	    if (next.has_value()) {
187	      BlockRef next_block = *next;
188	      BlockRef right = next_block.next();
189	      // Since the original block was not the last block (the sentinel last
190	      // block is never split), the split-off remainder block `next_block` is
191	      // also not the last block. Thus, its next block `right` is guaranteed
192	      // to be non-null.
193	      LIBC_ASSERT(right && "right block must be non-null");
194	      if (!right.used()) {
195	        free_store.remove(right);
196	        next_block.merge_next();
197	      }
198	      free_store.insert(next_block);
199	    }
200	    return true;
201	  }
202	  return false;
203	}
204	
205	// Follows constract of the C standard realloc() function
206	// If ptr is free'd, will return nullptr.
207	LIBC_INLINE void *FreeListHeap::realloc(void *ptr, size_t size) {
208	  if (size == 0) {
209	    free(ptr);
210	    return nullptr;
211	  }
212	
213	  // If the pointer is nullptr, allocate a new memory.
214	  if (ptr == nullptr)
215	    return allocate(size);
216	
