218	
219	  if (!is_valid_ptr(bytes))
220	    return nullptr;
221	
222	  BlockRef block = BlockRef::from_usable_space(bytes);
223	  if (!block.used())
224	    return nullptr;
225	  size_t old_size = block.inner_size();
226	
227	  if (old_size >= size) {
228	    shrink_in_place(block, size);
229	    return ptr;
230	  }
231	
232	  void *new_ptr = allocate(size);
233	  // Don't invalidate ptr if allocate(size) fails to initilize the memory.
234	  if (new_ptr == nullptr)
